import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve inventory details for all mining sites.
sites_response = session.get(f"{BASE_URL}/mining/sites")
sites_response.raise_for_status()
sites = sites_response.json()

for site in sites:
    site_id = site["id"]

    inventory_response = session.get(
        f"{BASE_URL}/mining/sites/{site_id}/materials"
    )
    inventory_response.raise_for_status()
    materials = inventory_response.json()

    # Apply recent stock changes supplied for each material.
    for material in materials:
        if "recent_stock_change" not in material:
            continue

        session.patch(
            f"{BASE_URL}/mining/sites/{site_id}/materials/{material['id']}",
            json={"stock_level": material["stock_level"] + material["recent_stock_change"]},
        ).raise_for_status()

        # Audit batches marked as critical.
        for batch in material.get("batches", []):
            if batch.get("critical"):
                session.post(
                    f"{BASE_URL}/sustainability/audits",
                    json={
                        "site_id": site_id,
                        "material_id": material["id"],
                        "batch_id": batch["id"],
                    },
                ).raise_for_status()

        # Create an inventory alert when a threshold is available.
        if "alert_threshold" in material:
            session.post(
                f"{BASE_URL}/alerts",
                json={
                    "site_id": site_id,
                    "material_id": material["id"],
                    "threshold": material["alert_threshold"],
                    "notification_enabled": True,
                },
            ).raise_for_status()

    # Allocate personnel to sites identified as having high workloads.
    if site.get("workload") == "high":
        session.post(
            f"{BASE_URL}/mining/sites/{site_id}/personnel/allocations",
            json={"additional_personnel": site.get("additional_personnel_needed", 1)},
        ).raise_for_status()

# Delete the outdated efficiency report.
reports_response = session.get(f"{BASE_URL}/reports")
reports_response.raise_for_status()
for report in reports_response.json():
    if report.get("type") == "efficiency" and report.get("outdated"):
        session.delete(f"{BASE_URL}/reports/{report['id']}").raise_for_status()

