import requests

BASE_URL = "https://api.socbench.example"

# Retrieve the top-rated products in every category.
response = requests.get(f"{BASE_URL}/products/top-rated")
response.raise_for_status()
categories = response.json()

# Collect unique product IDs and names from the top-rated results.
products = {}
for category in categories:
    for product in category.get("products", []):
        product_id = product.get("productId")
        if product_id:
            products[product_id] = product

# Fetch product descriptions and details using product search.
for product_id, product in products.items():
    name = product.get("productName", "")
    if name:
        search_response = requests.get(
            f"{BASE_URL}/products/search",
            params={"query": name, "page": 1, "size": 10},
        )
        search_response.raise_for_status()
        product["searchDetails"] = search_response.json()

# Retrieve available consumer trends and regional demand forecasts.
# The documented endpoints do not provide product-specific seasonal predictions
# or a forecast horizon, so request the available overview and forecast data.
trends_response = requests.get(f"{BASE_URL}/consumer-trends/overview")
trends_response.raise_for_status()
trends = trends_response.json()

forecast_response = requests.get(f"{BASE_URL}/inventory/demand-forecast")
forecast_response.raise_for_status()
demand_forecast = forecast_response.json()

# Retrieve prices for each product to allow retailer price comparisons.
prices_by_product = {}
for product_id in products:
    price_response = requests.get(
        f"{BASE_URL}/products/{product_id}/prices"
    )
    if price_response.status_code == 404:
        prices_by_product[product_id] = []
        continue
    price_response.raise_for_status()
    prices_by_product[product_id] = price_response.json()

# The documented API has no endpoint for submitting price updates or suggested
# changes. Report observed cross-retailer price differences without attempting
# an unsupported update request.
price_discrepancies = {}
for product_id, prices in prices_by_product.items():
    by_currency = {}
    for entry in prices:
        currency = entry.get("currency")
        price = entry.get("price")
        if currency is not None and isinstance(price, (int, float)):
            by_currency.setdefault(currency, []).append(entry)

    differences = {}
    for currency, entries in by_currency.items():
        if len(entries) > 1:
            values = [entry["price"] for entry in entries]
            if min(values) != max(values):
                differences[currency] = {
                    "minimum": min(values),
                    "maximum": max(values),
                    "retailers": entries,
                }
    if differences:
        price_discrepancies[product_id] = differences

result = {
    "topRatedProducts": categories,
    "productDetails": products,
    "consumerTrends": trends,
    "demandForecast": demand_forecast,
    "pricesByProduct": prices_by_product,
    "observedPriceDiscrepancies": price_discrepancies,
    "priceUpdateLimitation": (
        "No documented endpoint supports submitting price updates or suggested changes."
    ),
}
print(result)

import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

categories_response = session.get(f"{BASE_URL}/product-categories/top")
categories_response.raise_for_status()
top_categories = categories_response.json()
category_names = {
    item.get("category")
    for item in top_categories
    if isinstance(item, dict) and item.get("category")
}

inventory_response = session.get(f"{BASE_URL}/inventory-levels")
inventory_response.raise_for_status()
inventory_levels = inventory_response.json()

retailers_response = session.get(f"{BASE_URL}/retailers")
retailers_response.raise_for_status()
retailers = retailers_response.json()

retailers_with_matching_products = []
for retailer in retailers:
    retailer_id = retailer.get("retailer_id")
    if not retailer_id:
        continue

    products_response = session.get(
        f"{BASE_URL}/retailers/{retailer_id}/products"
    )
    products_response.raise_for_status()
    products = products_response.json()

    matching_products = [
        product
        for product in products
        if product.get("category") in category_names
    ]
    if matching_products:
        retailers_with_matching_products.append(
            {
                "retailer_id": retailer_id,
                "name": retailer.get("name"),
                "locations": retailer.get("locations", []),
                "products": matching_products,
            }
        )

inventory_by_product = {}
for item in inventory_levels:
    product_id = item.get("product_id")
    if product_id:
        inventory_by_product.setdefault(product_id, []).append(item)

category_product_ids = {
    product.get("product_id")
    for retailer in retailers_with_matching_products
    for product in retailer["products"]
    if product.get("product_id")
}
category_inventory = [
    level
    for product_id in category_product_ids
    for level in inventory_by_product.get(product_id, [])
]

gaps = []
for retailer in retailers_with_matching_products:
    for product in retailer["products"]:
        product_id = product.get("product_id")
        levels = inventory_by_product.get(product_id, [])
        if not levels:
            gaps.append(
                {
                    "type": "missing_inventory_data",
                    "retailer_id": retailer["retailer_id"],
                    "product_id": product_id,
                    "category": product.get("category"),
                }
            )
        else:
            for level in levels:
                if level.get("stock_level", 0) <= 0:
                    gaps.append(
                        {
                            "type": "no_stock",
                            "retailer_id": retailer["retailer_id"],
                            "product_id": product_id,
                            "location_id": level.get("location_id"),
                            "category": product.get("category"),
                        }
                    )

represented_categories = {
    product.get("category")
    for retailer in retailers_with_matching_products
    for product in retailer["products"]
}
for category in sorted(category_names - represented_categories):
    gaps.append(
        {
            "type": "category_not_represented_by_retailer_products",
            "category": category,
        }
    )

feedback = {
    "summary": "Availability and category representation findings from the demand and inventory analysis.",
    "gaps_or_discrepancies": gaps,
    "note": "No feedback submission endpoint is documented; findings are retained locally.",
}

result = {
    "top_categories": top_categories,
    "inventory_levels": inventory_levels,
    "category_inventory_levels": category_inventory,
    "retailers_with_matching_products": retailers_with_matching_products,
    "available_retailers": [
        {
            "retailer_id": retailer.get("retailer_id"),
            "name": retailer.get("name"),
            "locations": retailer.get("locations", []),
        }
        for retailer in retailers
    ],
    "feedback": feedback,
}

