import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve current grid usage statistics and active alerts.
usage_response = session.get(f"{BASE_URL}/grid/usage", timeout=30)
usage_response.raise_for_status()
usage_data = usage_response.json()

alerts_response = session.get(
    f"{BASE_URL}/alerts",
    params={"status": "active"},
    timeout=30,
)
alerts_response.raise_for_status()
alerts_data = alerts_response.json()

# Keep alerts that mention renewable energy or integration-related issues.
def mentions_renewables(value):
    terms = ("renewable", "solar", "wind", "hydro", "curtailment", "integration")
    if isinstance(value, dict):
        return any(mentions_renewables(item) for item in value.values())
    if isinstance(value, list):
        return any(mentions_renewables(item) for item in value)
    return isinstance(value, str) and any(term in value.lower() for term in terms)

active_alerts = alerts_data.get("alerts", alerts_data) if isinstance(alerts_data, dict) else alerts_data
renewable_alerts = [
    alert for alert in active_alerts
    if mentions_renewables(alert)
] if isinstance(active_alerts, list) else []

print({
    "current_usage_statistics": usage_data,
    "active_renewable_integration_alerts": renewable_alerts,
})
